def is_sum_of_3_squares(n):
    if n < 0: return False
    while n % 4 == 0:
        n //= 4
    return n % 8 != 7

def is_sum_of_2_squares(n):
    if n < 0: return False
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            if d % 4 == 3 and count % 2 == 1:
                return False
        d += 1
    if temp % 4 == 3:
        return False
    return True

for x in range(20):
    val = x**2 + 7
    print(f"x={x}, val={val}, sum_of_2={is_sum_of_2_squares(val)}, sum_of_3={is_sum_of_3_squares(val)}")
